def _is_exact_alias(left, right):
    return (
        left.data_ptr() == right.data_ptr()
        and left.storage_offset() == right.storage_offset()
        and left.shape == right.shape
        and left.stride() == right.stride()
    )


def ldexp_(self, other):
    logger.debug("GEMS_ENFLAME LDEXP_")
    if has_internal_overlapping(self) == MemOverlap.Yes:
        raise RuntimeError(
            "unsupported operation: more than one element of the written-to tensor "
            "refers to a single memory location"
        )
    if (
        self.device == other.device
        and self.untyped_storage().nbytes() > 0
        and self.untyped_storage().data_ptr() == other.untyped_storage().data_ptr()
        and not _is_exact_alias(self, other)
    ):
        temporary = torch.empty_like(other)
        if other.is_complex():
            real, imag = _complex_parts(
                other,
                torch.float64 if other.dtype == torch.complex128 else torch.float32,
            )
            _write_complex(temporary, real, imag)
        else:
            copy_(temporary, other)
        other = temporary

    result_dtype = _result_dtype(self, other)
    if not torch.can_cast(result_dtype, self.dtype):
        raise RuntimeError(
            f"result type {result_dtype} can't be cast to the desired output "
            f"type {self.dtype}"
        )

    output_shape = torch.broadcast_shapes(self.shape, other.shape)
    if output_shape != self.shape:
        raise RuntimeError(
            f"output with shape {self.shape} doesn't match the broadcast shape "
            f"{output_shape}"
        )

    integral_exponent = not other.is_floating_point() and not other.is_complex()
    # On GCU400 pointwise_dynamic misaligns the tail indices of a non-contiguous operand when the two inputs have
    # different strides
    # Index misalignment (see the note with the same name in ldexp.py); materialize a non-contiguous exponent tensor
    # first.
    if not other.is_contiguous():
        other = other.contiguous()
    if self.is_complex():
        if integral_exponent:
            _ldexp_complex_integral_(self, other)
        else:
            _ldexp_complex_(self, other)
    else:
        # Contiguous same-shape integral-tensor-exponent fast path: a single
        # flat kernel on the Fixed-Grid-48 + grid-stride idiom (see the
        # specialisation note above _ldexp_inplace_contig_kernel).  Every
        # condition below is required for the flat 1-D addressing to be
        # valid; anything else keeps the generic strided implementation.
        if (
            integral_exponent
            and other.dtype is torch.int32
            and self.dtype in _FAST_SELF_DTYPES
            and self.device.type == _DEVICE_NAME
            and self.is_contiguous()
            and self.shape == other.shape
            and 0 < self.numel() < _FLAT_INT32_LIMIT
        ):
            n_elements = self.numel()
            block_size, num_warps = _pick_ldexp_launch(n_elements, self.element_size())
            tiles = (n_elements + block_size - 1) // block_size
            grid = (_GRID_SIZE if tiles > _GRID_SIZE else tiles,)
            with torch_device_fn.device(self.device):
                _ldexp_inplace_contig_kernel[grid](
                    self,
                    other,
                    n_elements,
                    BLOCK_SIZE=block_size,
                    GRID_SIZE=grid[0],
                    num_warps=num_warps,
                )
            return self
        # The strided pointwise path mis-indexes the tail of a transposed
        # tensor (measured: shape (7, 19) with stride (1, 7) writes 0/garbage
        # into its last 3 columns), so compute into a contiguous buffer and
        # copy back.  The data pointer and stride of `self` are preserved.
        out_target = self
        src = self
        if not self.is_contiguous():
            src = self.contiguous()
            out_target = torch.empty(self.shape, dtype=self.dtype, device=self.device)
        if integral_exponent:
            func = (
                ldexp_inplace_integral_fp64_func
                if result_dtype == torch.float64
                else ldexp_inplace_integral_func
            )
        else:
            if result_dtype == torch.float64 and self.dtype != torch.float64:
                # float64 exponent with an fp32-or-narrower destination: the
                # fp32 scale is exact enough, and the fp64 kernel would need
                # an fp64 exp2 (libdevice has no fp64 exp2 on this backend).
                other = other.to(torch.float32)
                func = ldexp_inplace_func
            else:
                func = (
                    ldexp_inplace_fp64_func
                    if result_dtype == torch.float64
                    else ldexp_inplace_func
                )
        if integral_exponent:
            func(src, other, _WRAP_INTEGER_EXPONENT, out0=out_target)
        else:
            func(src, other, out0=out_target)
        if out_target is not self:
            torch.ops.aten.copy_.default.redispatch(
                _NATIVE_COPY_KEYSET, self, out_target, False
            )
    return self


